 function openBankModal(){const bankModal=document.getElementById('bankModal');if (bankModal){bankModal.style.display='block';}}function closeBankModal(){const bankModal=document.getElementById('bankModal');if (bankModal){bankModal.style.display='none';}}window.addEventListener('click',function(event){const bankModal=document.getElementById('bankModal');if (bankModal && event.target===bankModal){closeBankModal();}});function copyToClipboard(text,id){navigator.clipboard.writeText(text).then(function(){console.log('Text copied to clipboard',text);const element=document.getElementById(id);const originalText=element.textContent;const originalColor=element.style.color;element.textContent='Copied!';element.classList.add('copied');element.style.color='green';setTimeout(function(){element.style.transition='color 0.5s ease';element.style.color='#ffffff';setTimeout(function(){element.style.color=originalColor;element.textContent=originalText;element.classList.remove('copied');setTimeout(function(){element.style.transition='';},500);},500);},1000);}).catch(function(err){console.error('Could not copy text: ',err);alert('Could not copy to clipboard. Please copy manually: '+text);});}const hamburger=document.querySelector('.hamburger');const navMenu=document.querySelector('.nav-menu');if (hamburger && navMenu){hamburger.addEventListener('click',()=>{hamburger.classList.toggle('active');navMenu.classList.toggle('active');});document.querySelectorAll('.nav-link').forEach(n=> n.addEventListener('click',()=>{hamburger.classList.remove('active');navMenu.classList.remove('active');}));}const navLogo=document.querySelector('.nav-logo');if (navLogo){navLogo.addEventListener('click',()=>{window.location.href='index.html#top';});navLogo.style.cursor='pointer';}